-- Additive D1 workspace slice; never apply PostgreSQL migrations here.
PRAGMA foreign_keys=ON;
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120),owner_user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),quota_bytes INTEGER NOT NULL DEFAULT 9000000000 CHECK(quota_bytes>0));
CREATE INDEX workspace_owner_page ON workspaces(owner_user_id,created_at DESC,id DESC);
CREATE TABLE workspace_commands(actor_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,session_id TEXT NOT NULL,name TEXT NOT NULL,workspace_id TEXT NOT NULL UNIQUE,result_json TEXT,PRIMARY KEY(actor_id,request_id));
CREATE TRIGGER workspace_command_guard BEFORE INSERT ON workspace_commands BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM owners o JOIN owner_sessions s ON s.userId=o.user_id WHERE o.user_id=NEW.actor_id AND o.enabled=1 AND s.id=NEW.session_id AND s.expiresAt>unixepoch('subsec')*1000) THEN RAISE(ABORT,'OWNER_REQUIRED') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM workspace_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id AND name<>NEW.name) THEN RAISE(ABORT,'REQUEST_ID_CONFLICT') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM workspace_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id) THEN RAISE(IGNORE) END; SELECT CASE WHEN (SELECT count(*) FROM workspaces WHERE owner_user_id=NEW.actor_id)>=100 THEN RAISE(ABORT,'WORKSPACE_LIMIT_REACHED') END; END;
CREATE TRIGGER workspace_command_apply AFTER INSERT ON workspace_commands BEGIN INSERT INTO workspaces(id,name,owner_user_id) VALUES(NEW.workspace_id,NEW.name,NEW.actor_id); UPDATE workspace_commands SET result_json=(SELECT json_object('id',id,'name',name,'ownerUserId',owner_user_id,'role','workspace_owner','createdAt',created_at,'quotaBytes',quota_bytes) FROM workspaces WHERE id=NEW.workspace_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,action,after_json,request_id) SELECT 'workspace:'||NEW.workspace_id,'user',NEW.actor_id,NEW.session_id,NEW.workspace_id,'workspace.created',result_json,NEW.request_id FROM workspace_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER workspace_command_no_delete BEFORE DELETE ON workspace_commands BEGIN SELECT RAISE(ABORT,'IMMUTABLE_COMMAND'); END;
CREATE TRIGGER workspace_command_no_update BEFORE UPDATE ON workspace_commands WHEN OLD.result_json IS NOT NULL OR NEW.actor_id<>OLD.actor_id OR NEW.request_id<>OLD.request_id OR NEW.session_id<>OLD.session_id OR NEW.name<>OLD.name OR NEW.workspace_id<>OLD.workspace_id OR NEW.result_json IS NULL BEGIN SELECT RAISE(ABORT,'IMMUTABLE_COMMAND'); END;
